<script>
  import { randomString } from '@splendidlabz/utils/dom'
  import { useActions } from '../../actions/use-actions'
  import FieldMeta from './FieldMeta.svelte'

  let {
    value = $bindable(''),
    ref = $bindable(null),
    class: klass,
    style,
    labelClass,
    hintClass,
    errorClass,
    inputGroupClass,
    fieldClass,
    id = randomString(8),
    name,
    label = '',
    labelVisible = true,
    hint = null,
    error = null,
    disabled = null,
    readonly = null,
    actions = [],
    oninput = null,
    autogrow = false,

    // Slots
    before,
    after,
    children,

    ...rest
  } = $props()

  // IDs for aria-describedby
  const hintId = $derived(hint ? id + '-hint' : '')
  const errorId = $derived(id + '-error')
  const describedBy = $derived(`${hintId} ${errorId}`.trim() || null)

  // Mirrors the text, and fills a trailing newline so its line counts
  const replicaText = $derived(value + (value.endsWith('\n') ? '\u00a0' : ''))
</script>

<!-- Snippets -->
{#snippet textarea()}
  <textarea
    {...rest}
    bind:this={ref}
    {id}
    {name}
    class="input {fieldClass}"
    aria-describedby={describedBy}
    aria-invalid={error ? 'true' : null}
    aria-label={!labelVisible && label ? label : null}
    {disabled}
    {oninput}
    {readonly}
    bind:value
    use:useActions={actions}></textarea>
{/snippet}

<div
  {style}
  class="input-container textarea {klass}"
  class:disabled
  class:readonly
  class:textarea-autogrow={autogrow}
>
  <FieldMeta
    {id}
    {error}
    {errorClass}
    {hint}
    {hintClass}
    {label}
    {labelClass}
    {labelVisible}
  />

  {#if before || after}
    <div class="input-group {inputGroupClass}">
      {#if before}
        {@render before()}
        <div class="divider-vertical"></div>
      {/if}

      {@render textarea()}

      {#if after}
        <div class="divider-vertical"></div>
        {@render after()}
      {/if}
    </div>
  {:else}
    <div class="stack">
      <!-- Autogrow textarea cannot be used together with input-group cos it makes the CSS very complex -->
      {#if autogrow}
        <div class="replica-field field {fieldClass}" aria-hidden="true">
          {replicaText}
        </div>
      {/if}
      {@render textarea()}
    </div>
  {/if}
</div>
